function hydrate(x){const b=base();if(!x||typeof x!=="object")return b;const oldJob=x.job||{};const org=oldJob.organization||oldJob.name||b.job.organization;const title=oldJob.title||(String(oldJob.name||"").includes(" — ")?String(oldJob.name).split(" — ").slice(1).join(" — "):b.job.title);return{...b,...x,version:7,needs:{...b.needs,...(x.needs||{})},routine:{...b.routine,...(x.routine||{})},job:{...b.job,...oldJob,organization:org,title,source:oldJob.source||(org==="The Office"?"office":org==="Government"?"government":"standard"),scheduleStart:WORK_START,scheduleEnd:WORK_END},attendance:x.attendance&&typeof x.attendance==="object"?x.attendance:{},home:{...b.home,...(x.home||{})},diet:{...b.diet,...(x.diet||{})},relationship:{mikael:{...b.relationship.mikael,...(x.relationship?.mikael||{})}},stats:{...b.stats,...(x.stats||{})},family:mergePeople(b.family,x.family),npcs:mergePeople(b.npcs,x.npcs),officePeople:mergePeople(b.officePeople,x.officePeople),spector:{...b.spector,...(x.spector||{})},loans:Array.isArray(x.loans)?x.loans:[],legal:Array.isArray(x.legal)?x.legal.map(normalizeLegalCase):[],plans:Array.isArray(x.plans)?x.plans:[],pending:Array.isArray(x.pending)?x.pending:[],interviews:Array.isArray(x.interviews)?x.interviews:[],history:Array.isArray(x.history)?x.history:b.history,activity:Array.isArray(x.activity)?x.activity:[],workGame:null};}
function load(){try{return hydrate(JSON.parse(localStorage.getItem(KEY)||"null"))}catch{return base()}}
