function parts(min=s.lifeMinute){const d=Math.floor(min/1440),year=Math.floor(d/365)+1,yd=((d%365)+365)%365;let left=yd,m=0;while(m<11&&left>=MONTHS[m][1])left-=MONTHS[m++][1];const md=((min%1440)+1440)%1440,h=Math.floor(md/60),mm=md%60;let period="Late Night";if(h>=5&&h<8)period="Early Morning";else if(h>=8&&h<12)period="Morning";else if(h>=12&&h<17)period="Mid Day";else if(h>=17&&h<21)period="Evening";return{absDay:d,year,month:m+1,monthName:MONTHS[m][0],day:left+1,dayName:DAYS[((d%7)+7)%7],hour:h,minute:mm,minuteOfDay:md,season:m<=1||m===11?"Summer":m<=4?"Autumn":m<=7?"Winter":"Spring",period};}
const absDay=()=>Math.floor(s.lifeMinute/1440);
const clock=m=>`${String(Math.floor(m/60)%24).padStart(2,"0")}:${String(m%60).padStart(2,"0")}`;
