function activity(text,icon="•"){s.activity.push({day:absDay(),minute:s.lifeMinute,text,icon});s.activity=s.activity.slice(-160)}
function history(text,icon="📌"){s.history.push({year:parts().year,text,icon});s.history=s.history.slice(-200)}
function spend(n,why){n=Math.round(Number(n)||0);if(s.cash<n)return false;s.cash-=n;s.stats.spent+=n;activity(`-${n} LB · ${why}`,"💸");return true}
function earn(n,why){n=Math.round(Number(n)||0);s.cash+=n;s.stats.earned+=n;activity(`+${n} LB · ${why}`,"💰")}
const workday=d=>((d%7)+7)%7<5;
function attendanceKey(day){return String(day)}
