function isOfficeJob(){return s.job.employed&&(s.job.source==="office"||jobOrg()==="The Office")}
function parseLegalTerms(t){const type=String(t?.type||"probono"),raw=String(t?.value||"");const nums=(raw.match(/\d+(?:\.\d+)?/g)||[]).map(Number);if(type==="percentage")return{type,fixed:0,pct:Math.max(0,Math.min(100,nums[0]||0)),label:`${nums[0]||0}% of settlement`};if(type==="combination")return{type,fixed:Math.max(0,nums[0]||0),pct:Math.max(0,Math.min(100,nums[1]||0)),label:`${nums[0]||0} LB + ${nums[1]||0}%`};if(type==="retainer"||type==="fixed")return{type,fixed:Math.max(0,nums[0]||0),pct:0,label:`${nums[0]||0} LB ${type}`};return{type:"probono",fixed:0,pct:0,label:"Pro bono"}}
function createCase(reason,defendant="Unknown Defendant",claimAmount=500,origin="life",autoRequest=true){const c=normalizeLegalCase({id:uid("case"),reason:String(reason),defendant:String(defendant),claimAmount:Math.max(50,Math.round(Number(claimAmount)||500)),status:autoRequest?"requested":"not_requested",createdLifeMinute:s.lifeMinute,origin,terms:null,verdict:null,transcript:[]});s.legal.push(c);s.stats.lawsuits++;activity(`${autoRequest?"Asked Mikael Spector to sue":"Potential lawsuit"}: ${c.defendant} — ${c.reason} (${c.claimAmount} LB claim).`,"⚖️");history(`Legal claim against ${c.defendant}: ${c.reason}`,"⚖️");return c}
function requestSpector(c){if(!c)return;c.status="requested";activity(`Requested Mikael Spector for case against ${c.defendant}.`,"⚖️")}
function applyCourtVerdict(c,payload){if(!c||c.status==="verdict")return;const won=!!payload.won,award=won?Math.max(0,Math.round(Number(payload.award)||0)):0,terms=parseLegalTerms(c.terms),fee=Math.round(terms.fixed+(won?award*terms.pct/100:0));let paid=0,outstanding=0,net=0;if(won){paid=Math.min(fee,award);net=Math.max(0,award-paid);if(net)earn(net,`Court award vs ${c.defendant} after Mikael Spector fees`);if(fee>award)outstanding=fee-award}else{paid=Math.min(s.cash,fee);if(paid){s.cash-=paid;s.stats.spent+=paid;activity(`-${paid} LB · Mikael Spector legal fee`,"⚖️")}outstanding=Math.max(0,fee-paid)}s.spector.earned+=paid;s.spector.outstanding+=outstanding;s.stats.spectorFees+=paid;if(won)s.stats.lawsuitsWon++;c.status="verdict";c.verdict={won,award,fee,paid,outstanding,net,summary:String(payload.summary||""),judgeNote:String(payload.judgeNote||""),at:s.lifeMinute};c.transcript=Array.isArray(payload.transcript)?payload.transcript.slice(0,80):[];activity(won?`COURT WIN: ${award} LB awarded. Mikael Spector received ${paid} LB; Lizzy received ${net} LB.`:`COURT LOSS: no award. Mikael Spector fee paid ${paid} LB${outstanding?`, ${outstanding} LB still due`:""}.`,won?"🏆":"⚖️");history(`${won?"Won":"Lost"} case against ${c.defendant}. ${won?`${award} LB awarded.`:"No damages awarded."}`,won?"🏆":"⚖️");s.currentEvent={emoji:won?"🏆":"⚖️",title:won?"COURT VICTORY":"COURT VERDICT",text:`${won?`You won ${award} LB against ${c.defendant}. After Mikael Spector received ${paid} LB, you got ${net} LB.`:`The court ruled against you in the case against ${c.defendant}.`}${outstanding?` Legal fees still due: ${outstanding} LB.`:""} You can read the full court transcript in Story & Calendar.`,choices:[["Read it later","close"]]}}
function quitJob(){if(!s.job.employed)return alert("You are already unemployed.");const prev={...s.job};if(!confirm(`Quit ${jobDisplay()}?`))return;s.lastEmployer=prev;s.job.employed=false;s.job.missedConsecutive=0;s.stats.quits++;activity(`Quit ${prev.organization||prev.name} — ${prev.title||"job"}.`,"🚪");history(`Quit ${prev.organization||prev.name}.`,"🚪");s.currentEvent={emoji:"🚪",title:"YOU QUIT",text:"A mature career decision has occurred. You may leave peacefully, sue the company, or sue a coworker for something suspiciously specific.",choices:[["Leave gracefully","close"],["⚖️ Sue the Company","quit_sue_company"],["⚖️ Sue a Coworker","quit_sue_coworker"]]}}
