function fire(reason){if(!s.job.employed)return;const prev={...s.job};s.lastEmployer=prev;s.job.employed=false;s.job.missedConsecutive=0;s.stats.fired++;createCase(reason,prev.organization||prev.name||"Former Employer",Math.round(700+Math.random()*1800),"firing",false);s.currentEvent={emoji:"🔥",title:"YOU HAVE BEEN FIRED",text:reason,choices:[["⚖️ Hire Mikael Spector","lawyer"],["⚖️ Sue Employer Immediately","fire_sue_company"],["😡 Insult Former Boss","insultboss"],["📝 Find Another Job","findjob"],["🛋️ Become Unemployed","close"]]};activity(`FIRED: ${reason}`,"🔥");history(`Fired from ${prev.organization||prev.name}: ${reason}`,"🔥")}
function markMissed(day,reason="Missed the 09:00–17:00 shift."){if(!s.job.employed||!workday(day)||s.attendance[attendanceKey(day)])return;s.attendance[attendanceKey(day)]={status:"missed",reason};s.job.missedConsecutive++;activity(`${reason} (${s.job.missedConsecutive}/3)`,"🚫");if(s.job.missedConsecutive>=3)fire("Three consecutive workdays were missed. Your boss skipped the check-up messages and went directly to firing you.")}
function autoWork(day){if(!s.job.employed||!workday(day)||s.attendance[attendanceKey(day)])return;s.attendance[attendanceKey(day)]={status:"worked",auto:true};s.job.missedConsecutive=0;earn(s.job.salary,`${s.job.name} salary (auto-attended during skip)`);s.job.performance=clamp(s.job.performance+1)}
function processNewDay(day){if(day>=s.diet.nextRenewAbsDay){if(s.diet.autoRenew&&spend(s.diet.cost,`${s.diet.name} groceries`))s.diet.nextRenewAbsDay=day+14;else{s.pending.push({id:uid("diet"),kind:"diet_due",title:"Groceries need attention",status:"pending"});s.diet.nextRenewAbsDay=day+1}}
 const p=parts(day*1440+720);if(!s.home.owned&&s.home.rent>0&&p.day===1)spend(s.home.rent,`${s.home.name} rent`);
 for(const l of s.loans.filter(x=>x.status==="active"&&day>=x.nextPaymentDay)){const pay=Math.min(l.payment,l.balance);if(spend(pay,"Bank of Micky loan payment")){l.balance-=pay;l.nextPaymentDay=day+30;if(l.balance<=0)l.status="paid"}}
 if(day>0&&day%365===0){const yr=Math.floor(day/365);s.wrapped={year:yr,stats:{...s.stats},cash:s.cash};history(`Completed Life Year ${yr}.`,"🎆")}}
