function expireInterviews(day){for(const i of s.interviews.filter(x=>x.status==="scheduled"&&Math.floor(x.scheduledMinute/1440)===day)){const deadline=day*1440+INTERVIEW_END;if(s.lifeMinute>=deadline){i.status="missed";i.missedAt=s.lifeMinute;activity(`Missed ${i.organization} interview.`,"😬");history(`Missed an interview with ${i.recruiter}.`,"😬")}}}
function advance(mins,{autoWorkDuringSkip=false,draw=true,sync=true}={}){mins=Math.max(0,Math.floor(mins));const target=s.lifeMinute+mins;while(s.lifeMinute<target){const day=absDay(),dayStart=day*1440,workEnd=dayStart+WORK_END,noon=dayStart+INTERVIEW_END,midnight=(day+1)*1440;let next=target;if(s.lifeMinute<workEnd&&workEnd<=next)next=workEnd;if(s.lifeMinute<noon&&noon<=next)next=noon;if(midnight<=next)next=midnight;s.lifeMinute=next;if(next===workEnd){if(autoWorkDuringSkip)autoWork(day);else markMissed(day)}if(next===noon)expireInterviews(day);if(next===midnight)processNewDay(day+1)}processPlans();expireInterviews(absDay());save();if(draw)render();if(sync)pushSnapshot()}
