function interviewDue(i){const p=parts(),d=Math.floor(i.scheduledMinute/1440);return i.status==="scheduled"&&p.absDay===d&&p.minuteOfDay>=8*60&&p.minuteOfDay<INTERVIEW_END}
function startInterview(id){const i=s.interviews.find(x=>x.id===id);if(!i||i.status!=="scheduled")return;const d=Math.floor(i.scheduledMinute/1440),now=parts();if(now.absDay<d)return alert("That interview is tomorrow morning.");if(now.absDay>d||now.minuteOfDay>=INTERVIEW_END){i.status="missed";save();render();pushSnapshot();return}if(s.lifeMinute<i.scheduledMinute)advance(i.scheduledMinute-s.lifeMinute,{draw:false,sync:false});i.status="in_progress";activity(`Started interview with ${i.recruiter}.`,i.source==="office"?"📎":"🏛️");save();render();pushSnapshot()}
function submitInterview(id){const i=s.interviews.find(x=>x.id===id);if(!i||i.status!=="in_progress")return;const answers=i.questions.map((q,idx)=>String(ROOT.querySelector(`[data-interview-answer="${CSS.escape(id)}-${idx}"]`)?.value||"").trim());if(answers.some(x=>!x))return alert("Answer all three questions before submitting.");i.answers=answers.map((answer,idx)=>({question:i.questions[idx],answer}));i.status="awaiting_hq";i.submittedMinute=s.lifeMinute;advance(60,{draw:false,sync:false});activity(`Interview finished. One Life hour passed. ${i.recruiter} will send a decision through HQ soon.`,"🕐");history(`Completed ${i.organization} interview; awaiting hiring decision.`,i.source==="office"?"📎":"🏛️");s.currentEvent={emoji:"📨",title:"INTERVIEW SENT TO HQ",text:`Your answers have been sent. You will receive an answer soon telling you whether you got the job or whether a contract offer is coming.`,choices:[["Okay","close"]]};save();render();pushSnapshot()}
function acceptContract(id){const i=s.interviews.find(x=>x.id===id),c=i?.contract;if(!i||!c||c.status!=="offered")return;c.status="accepted";i.status="hired";s.job={id:`${i.source}-${i.id}`,name:i.organization,organization:i.organization,title:c.jobTitle,source:i.source,salary:c.salary,emoji:i.source==="office"?"📎":"🏛️",boss:i.recruiter,employed:true,missedConsecutive:0,careerXP:0,performance:55,scheduleStart:WORK_START,scheduleEnd:WORK_END};s.stats.jobsHeld++;activity(`Accepted ${i.organization} contract at ${c.salary} LB/workday. Work is 09:00–17:00.`,"🤝");history(`Hired by ${i.organization} as ${c.jobTitle}.`,"💼");save();render();pushSnapshot()}
function counterContract(id){const i=s.interviews.find(x=>x.id===id),c=i?.contract;if(!i||!c||c.status!=="offered")return;const el=ROOT.querySelector(`[data-counter-input="${CSS.escape(id)}"]`),amount=Math.max(1,Math.round(Number(el?.value)||0));if(!amount)return alert("Enter the salary you want to counter with.");c.counterSalary=amount;c.status="countered";i.status="countered";activity(`Countered ${i.organization}: asking for ${amount} LB/workday.`,"💬");save();render();pushSnapshot()}
function declineContract(id){const i=s.interviews.find(x=>x.id===id),c=i?.contract;if(!i||!c)return;c.status="declined";i.status="declined_contract";activity(`Declined ${i.organization} contract.`,"📭");save();render();pushSnapshot()}
function pendingHTML(){const ps=s.pending.filter(x=>x.status==="pending");const recruitment=ps.map(p=>`<div class="pending"><b>${p.kind==="recruitment"?(p.source==="office"?"📎 THE OFFICE · ":"🏛️ GOVERNMENT · "):""}${esc(p.title)}</b>${p.kind==="recruitment"?`<small>${esc(p.recruiter||"")} · ${esc(p.organization||"")}</small>`:""}<p>${esc(p.detail||"")}</p><div class="row">${p.kind==="mikael_invite"?`<button data-decision="accept" data-id="${esc(p.id)}">❤️ Accept</button><button data-decision="reject" data-id="${esc(p.id)}">Reject</button><button data-decision="laugh" data-id="${esc(p.id)}">😂 Laugh</button>`:`<button data-decision="accept" data-id="${esc(p.id)}">${p.source==="office"?"📎 Accept Michael Scott Interview":"🏛️ Accept President Interview"}</button><button data-decision="reject" data-id="${esc(p.id)}">Decline</button>`}</div></div>`).join("");const contracts=s.interviews.filter(i=>i.status==="offer_received"&&i.contract?.status==="offered").map(i=>`<div class="pending contract"><b>📄 CONTRACT OFFER · ${esc(i.organization)}</b><small>${esc(i.contract.jobTitle)} · 09:00–17:00</small><p><strong>${i.contract.salary} LB per workday</strong>${i.contract.note?`<br>${esc(i.contract.note)}`:""}</p><div class="counter"><input type="number" min="1" value="${i.contract.salary+10}" data-counter-input="${esc(i.id)}"><button data-contractaction="counter" data-id="${esc(i.id)}">💬 Counter Salary</button></div><div class="row"><button data-contractaction="accept" data-id="${esc(i.id)}">✅ Accept Contract</button><button data-contractaction="decline" data-id="${esc(i.id)}">Decline</button></div></div>`).join("");return recruitment+contracts||'<div class="empty">No protected decisions waiting.</div>'}
function decision(id,a){const p=s.pending.find(x=>x.id===id);if(!p)return;if(p.kind==="mikael_invite"){if(a==="accept"){p.status="accepted";const day=absDay()+p.daysAhead;s.plans.push({id:uid("plan"),inviteId:p.id,title:p.title,withMikael:true,status:"accepted",lifeMinute:day*1440+p.timeMinute});activity(`${p.title} added to calendar.`,"❤️")}else{p.status="rejected";if(a==="laugh")s.relationship.mikael.annoyance=clamp(s.relationship.mikael.annoyance+4)}}else if(p.kind==="recruitment"){p.status=a==="accept"?"accepted":"rejected";if(a==="accept")makeInterviewFromRecruitment(p)}save();render();pushSnapshot()}
function need(label,v){v=clamp(Math.round(v));return `<div class="need ${v<25?"bad":""}">${label}<div class="bar"><i style="width:${v}%"></i></div><b>${v}</b></div>`}
function officePanelHTML(){if(!isOfficeJob())return"";const atWork=s.location==="work";return `<div class="card office-rel"><h3>📎 The Office — Coworkers</h3><p class="muted">${atWork?"Choose a coworker and actually interact with them.":"You're away from the office. You can still text coworkers for 0 Life time; go to Work for full interactions."}</p><div class="officepeople">${Object.entries(s.officePeople).map(([id,p])=>{const m=OFFICE_CHARACTER_META[id];return `<article><div><b>${m.emoji} ${esc(m.name)}</b><small>${esc(p.status)} · ❤️ ${Math.round(p.friendship)} · 🤝 ${Math.round(p.trust)} · 😤 ${Math.round(p.annoyance)} · ✨ ${Math.round(p.chemistry)}</small></div><div class="row">${atWork?`<button data-office="chat" data-person="${id}">💬 Talk</button><button data-office="hangout" data-person="${id}">Hang Out · 1h</button><button data-office="flirt" data-person="${id}">Flirt · 30m</button><button data-office="annoy" data-person="${id}">Annoy · 30m</button><button data-office="special" data-person="${id}">🎭 Character Interaction</button>`:`<button data-office="text" data-person="${id}">📱 Text ${esc(m.name)} · 0m</button>`}</div></article>`}).join("")}</div></div>`}
