function interviewHTML(){const live=s.interviews.find(i=>i.status==="in_progress");if(live)return `<div class="event interview"><div class="emoji">${live.source==="office"?"📎":"🏛️"}</div><div><small>LIVE INTERVIEW · ${esc(live.organization)}</small><h3>${esc(live.recruiter)} is interviewing you</h3><p>Answer all three. Typing does not move Life time. Submitting the interview advances exactly <b>1 Life hour</b>.</p>${live.questions.map((q,idx)=>`<label class="q"><b>${idx+1}. ${esc(q)}</b><textarea data-interview-answer="${esc(live.id)}-${idx}" placeholder="Type your answer..."></textarea></label>`).join("")}<button class="primaryish" data-submitinterview="${esc(live.id)}">Submit Answers · +1h</button></div></div>`;const due=s.interviews.filter(interviewDue);if(!due.length)return"";return due.map(i=>`<div class="event interview ready"><div class="emoji">${i.source==="office"?"📎":"🏛️"}</div><div><small>INTERVIEW DUE THIS MORNING</small><h3>${esc(i.recruiter)} · ${esc(i.organization)}</h3><p>Scheduled for 09:00. Morning interview window closes at 12:00.</p><button data-startinterview="${esc(i.id)}">Start Interview</button></div></div>`).join("")}
